Let $c_n = f(n)$ and write $\beta = \lceil \alpha+1 \rceil$.

$$
\boxed{
\begin{cases}
0<\alpha\le 1:\quad f(n)=cn\ \ (n\ge1),\ \ c\in\mathbb{R};\\[2mm]
\alpha>1:\quad f(1),\dots,f(\beta-1)\ \text{are arbitrary real numbers, and for every }n\ge\beta\text{ the value }f(n)\text{ is uniquely determined (linearly) by them,}
\end{cases}
}
$$
i.e. for $\alpha>1$ the equation $f(k+m)=f(k)+f(m)$ ($\alpha m\le k\le(\alpha+1)m$) is equivalent to the system
$$
f(n)=f(\lfloor\alpha m\rfloor)+f(m)\qquad\text{for all }m\ge1\text{ with }\lfloor\alpha m\rfloor\ge m\ \ (m\ge\lceil1/\alpha\rceil),
$$
which is triangular and consistent, so the solution space is $\mathbb{R}^{\,\beta-1}$ with $f(n)$ for $n\ge\beta$ given by these linear relations.

\boxed{\begin{minipage}{0.92\linewidth}
\textbf{Case 1: } 0<\alpha\le 1:\quad \text{the only solutions are } f(n)=cn,\; c\in\mathbb R.\
\textbf{Case 2: } \alpha>1.\text{ Let } T=\{\,n\in\mathbb N^{+}:\exists j\in\{0,1,\dots,\lfloor\alpha\rfloor\}\text{ with }j(\alpha+2)<n<(j+1)(\alpha+1)\,\}\
\text{so that } |T|=\lfloor\alpha\rfloor+1-\alpha+\mathbf 1_{\{\alpha\notin\mathbb Z\}}.\text{ Then } f \text{ is any function satisfying}\
\qquad f(n)=cn\ \ (n\ge \lfloor\alpha\rfloor+2),\quad c\in\mathbb R,\text{ and } f\text{ arbitrary on }T,\
\text{extended to all }n\text{ by } f(k+m)=f(k)+f(m)\text{ whenever } \alpha m\le k\le(\alpha+1)m.\
\text{Equivalently, choose arbitrary } (f(n))_{n\in T}\text{ and set } c:=f(\lfloor\alpha\rfloor+2)/(\lfloor\alpha\rfloor+2);
\text{ then }f(n)=cn\ (n\ge\lfloor\alpha\rfloor+2)\text{ and } f(k+m)=f(k)+f(m)\text{ on the admissible pairs.}
\end{minipage}}
